#include <bits/stdc++.h>
using namespace std;

string normalize(const string& s) {
    string result;
    for (size_t i = 0; i < s.size(); ++i) {
        unsigned char c = s[i];

        if (c == 0xC3 && i + 1 < s.size()) {
            unsigned char accent = s[++i];
            switch (accent) {
                case 0x80: case 0x81: case 0x82: case 0x83: case 0x84: case 0x85:
                    result += 'a'; break;
                case 0x87:
                    result += 'c'; break;
                case 0x88: case 0x89: case 0x8A: case 0x8B:
                    result += 'e'; break;
                case 0x8C: case 0x8D: case 0x8E: case 0x8F:
                    result += 'i'; break;
                case 0x91:
                    result += 'n'; break;
                case 0x92: case 0x93: case 0x94: case 0x95: case 0x96:
                    result += 'o'; break;
                case 0x99: case 0x9A: case 0x9B:
                    result += 'u'; break;
                case 0x9D:
                    result += 'y'; break;
                default:
                    result += static_cast<char>(c);
                    result += static_cast<char>(accent);
            }
        } else {
            result += static_cast<char>(c);
        }
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string P, A;
    cin >> P >> A;

    P = normalize(P);
    A = normalize(A);

    int countP[26] = {};
    int countA[26] = {};

    for (char c : P) {
        if ('a' <= c && c <= 'z') ++countP[c - 'a'];
    }

    for (char c : A) {
        if ('a' <= c && c <= 'z') ++countA[c - 'a'];
    }

    for (int i = 0; i < 26; ++i) {
        if (countA[i] > countP[i]) {
            cout << "N\n";
            return 0;
        }
    }

    cout << "S\n";
    return 0;
}
